$g=[IO.File]::ReadAllText($(if($env:MK_SRC){$env:MK_SRC}else{'C:\claudecode\dark raiders\dark_raiders.html'}))
function L([string]$rx){ $m=[regex]::Matches($g,$rx); if($m.Count -ne 1){ throw "anchor $rx matched $($m.Count)" }; return $m[0].Value.Replace("`r",'') }
$a1=L "#root #codexmodal \.cxt \.cxr, #root #codexmodal \.cxt \.cxk\{[^\r\n]*"
$css=@'

/* v28.xx (cw-uc-codexfill) b-31 step 7, critic on 65 (P0 "nearly 40% of the card is empty", P1 "tile text about 14px, gun art small", P2 "new tag tiny"): the four rows now stretch to fill the card (rows 150px at least), gun art 96px, names 24px, tag lines 18px, the new chip 16px text. Layout only, no words changed. */
#root #codexmodal .cxgrid{ grid-auto-rows:minmax(150px, 1fr); align-content:stretch; gap:var(--sp-3); }
#root #codexmodal .cxt{ padding:var(--sp-2) var(--sp-3); gap:var(--sp-3); }
#root #codexmodal .cxt .cxi{ width:96px; height:96px; }
#root #codexmodal .cxt .cxi img{ width:88px; height:auto; max-height:88px; object-fit:contain; }
#root #codexmodal .cxt .cxn{ font-size:24px; }
#root #codexmodal .cxt .cxr, #root #codexmodal .cxt .cxk{ font-size:18px; }
#root #codexmodal .cxt .cxnew{ font-size:16px; padding:2px 8px; top:8px; right:8px; }
'@.Replace("`r",'')
$r1=$a1+$css.TrimEnd("`n")
$chk=@'
  {v:'VER',what:'codex tiles fill the card: 150px rows, 24px names, 96px art frame',
   run:function(){
     var bad=[], el, cs;
     __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     try{
       try{ openCodex(); }catch(_o){}
       el=document.querySelector('#codexmodal .cxt');
       if(!el) bad.push('no codex tile');
       else {
         if(el.getBoundingClientRect().height<149) bad.push('tile height '+el.getBoundingClientRect().height);
         cs=getComputedStyle(el.querySelector('.cxn')); if(cs.fontSize!=='24px') bad.push('name size '+cs.fontSize);
         cs=getComputedStyle(el.querySelector('.cxi')); if(cs.width!=='96px') bad.push('art frame '+cs.width);
       }
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{ try{ document.getElementById('codexmodal').classList.remove('on'); }catch(_c){} try{ __topClear(); }catch(_c2){} }
     return bad.length?bad.join('; '):null; }},
'@.Replace("`r",'')
$d=[ordered]@{
  title='UNDERCROFT: CODEX FILLS ITS CARD'
  why='Critic b-31 on the codex (65 at 2): the four rows sat in the top half with a dead lower half, 14px tag lines, small art. Rows now stretch (150px or more), art 96px, names 24px, tag lines 18px.'
  now='The codex tiles are bigger and fill the card.'
  edits=@( [ordered]@{ anchor=$a1; replacement=$r1 } )
  check=$chk
}
[IO.File]::WriteAllText('C:\claudecode\dark raiders\tools\handoff\drafts\draft-cw-uc-codexfill.json',($d | ConvertTo-Json -Depth 6),(New-Object Text.UTF8Encoding $false))
'written'

